import {esc,money} from './core.js?v=11';
import {placeForAirport,airportName} from './localities.js?v=11';
export const cityName=code=>placeForAirport(code)?.city||code;
export const travelDate=s=>new Date(String(s).slice(0,10)+'T12:00:00').toLocaleDateString('pt-BR',{weekday:'short',day:'numeric',month:'short'});
const time=s=>String(s||'').slice(11,16)||'—';
const duration=n=>Number.isFinite(n)?`${Math.floor(n/60)} h${n%60?' '+n%60+' min':''}`:'Duração a confirmar';
export function purchaseFor(p){if(p.demo)return null;const q=p.quotes?.at(-1);if(!q||!Number.isFinite(q.price)||q.price<=0)return null;try{const u=new URL(q.url);if(u.protocol!=='https:'||u.username||u.password)return null;return {url:u.href,price:q.price,total:Number.isFinite(q.total)&&q.total>0&&Math.abs(q.total-q.price*2)<.02?q.total:q.price*2,at:q.at,source:q.source};}catch{return null;}}
export function matchedOffer(p){const o=p.bestOffer,q=p.quotes?.at(-1);if(!o||!q||o.perPerson!==q.price||o.bookingUrl!==q.url||!Array.isArray(o.flights)||o.flights.length!==2)return null;const [a,b]=o.flights;if(!a.legs?.length||!b.legs?.length)return null;return a.legs[0].origin===p.origin&&a.legs.at(-1).dest===p.destination&&a.legs[0].depDate===p.depart&&b.legs[0].origin===p.destination&&b.legs.at(-1).dest===p.origin&&b.legs[0].depDate===p.return?o:null;}
export function flightPanel(f,index,trip){const start=f?.legs?.[0],end=f?.legs?.at(-1),origin=start?.origin||(index?trip.destination:trip.origin),destination=end?.dest||(index?trip.origin:trip.destination),date=start?.departure||(index?trip.return:trip.depart);return `<section class="journey-flight"><header><span class="flight-symbol" aria-hidden="true">${index?'↘':'↗'} ✈</span><h3>Voo de ${index?'volta':'ida'} <span>· ${esc(travelDate(date))}</span></h3></header><div class="journey-flight-body"><div class="journey-timeline"><div><strong>${start?esc(time(start.departure)):'—'}</strong><small>${esc(origin)}</small></div><div class="journey-track"><i></i><span>${start?duration(f.duration):'Horários a consultar'}</span></div><div><strong>${end?esc(time(end.arrival)):'—'}</strong><small>${esc(destination)}</small></div></div>${start?`<div class="journey-airline"><span class="airline-monogram">${esc(start.airline)}</span><div><strong>${esc(f.airlineName||start.airlineName||start.airline)}</strong><small>${f.stops?`${f.stops} parada${f.stops>1?'s':''}${f.legs.length>1?' em '+f.legs.slice(0,-1).map(l=>esc(l.dest)).join(', '):''}`:'Sem escalas'}${end.arrival.slice(0,10)!==start.departure.slice(0,10)?' · chegada '+esc(travelDate(end.arrival)):''}</small></div></div><details class="flight-more"><summary>Ver aeroportos e detalhes</summary>${f.legs.map(l=>`<div class="flight-segment"><strong>${esc(l.airlineName||l.airline)} · ${esc(l.airline)} ${esc(l.flightNumber)}</strong><p>${esc(airportName(l.origin))}<br><b>${esc(time(l.departure))}</b> · ${esc(travelDate(l.departure))}</p><p>${esc(airportName(l.dest))}<br><b>${esc(time(l.arrival))}</b> · ${esc(travelDate(l.arrival))}</p></div>`).join('')}<p class="flight-local-time">Horários locais de cada aeroporto.</p></details>`:`<p class="journey-pending">${esc(cityName(origin))} → ${esc(cityName(destination))}</p>`}</div></section>`;}
const cache=new Map(),inflight=new Map();
const wikiTitles={SSA:'Salvador',GRU:'São Paulo',CGH:'São Paulo',GIG:'Rio de Janeiro',SDU:'Rio de Janeiro',BSB:'Brasília',CNF:'Belo Horizonte',LIS:'Lisboa',CDG:'Paris',ORY:'Paris',HND:'Tóquio',NRT:'Tóquio',JFK:'Nova Iorque',EWR:'Nova Iorque',LGA:'Nova Iorque',EZE:'Buenos Aires',AEP:'Buenos Aires',SCL:'Santiago do Chile',LHR:'Londres',LGW:'Londres'};
export function destinationCover(p,content='',extra=''){return `<div class="destination-cover ${extra}" data-destination="${esc(p.destination)}" data-destination-city="${esc(p.city||cityName(p.destination))}"><span class="destination-placeholder" aria-hidden="true">✈</span><img class="destination-image" alt="Vista de ${esc(p.city||cityName(p.destination))}" loading="lazy" decoding="async" hidden referrerpolicy="no-referrer"><div class="destination-overlay"></div>${content}<a class="destination-credit" target="_blank" rel="noopener noreferrer" hidden>Foto · Wikimedia Commons</a></div>`;}
const plain=s=>String(s||'').replace(/<[^>]*>/g,'').slice(0,180);
async function photo(code,city){const key=wikiTitles[code]||city;if(cache.has(key))return cache.get(key);if(inflight.has(key))return inflight.get(key);const work=(async()=>{try{const saved=JSON.parse(localStorage.getItem('aeroping-photo:'+key)||'null');if(saved&&Date.now()-saved.at<7*86400000&&saved.url?.startsWith('https://')&&['upload.wikimedia.org','thumb.wikimedia.org'].includes(new URL(saved.url).hostname)&&saved.credit?.startsWith('https://commons.wikimedia.org/wiki/')){cache.set(key,saved);return saved;}}catch{}const params=new URLSearchParams({action:'query',format:'json',origin:'*',prop:'pageimages',piprop:'thumbnail|name',pithumbsize:'960',pilicense:'free',titles:key});const r=await fetch('https://pt.wikipedia.org/w/api.php?'+params,{signal:AbortSignal.timeout(7000)});if(!r.ok)throw Error('Photo unavailable');const data=await r.json(),page=Object.values(data.query?.pages||{})[0],raw=page?.thumbnail?.source;if(!raw||!page.pageimage)return null;const url=new URL(raw);if(url.protocol!=='https:'||!['upload.wikimedia.org','thumb.wikimedia.org'].includes(url.hostname))return null;url.search='';const file='File:'+page.pageimage;const infoParams=new URLSearchParams({action:'query',format:'json',origin:'*',prop:'imageinfo',iiprop:'extmetadata',titles:file});const metaR=await fetch('https://commons.wikimedia.org/w/api.php?'+infoParams,{signal:AbortSignal.timeout(7000)});if(!metaR.ok)return null;const metaData=await metaR.json(),entry=Object.values(metaData.query?.pages||{})[0]?.imageinfo?.[0]?.extmetadata;if(!entry)return null;const item={url:url.href,credit:'https://commons.wikimedia.org/wiki/'+encodeURIComponent(file),author:plain(entry.Artist?.value),license:plain(entry.LicenseShortName?.value),at:Date.now()};cache.set(key,item);try{localStorage.setItem('aeroping-photo:'+key,JSON.stringify(item));}catch{}return item;})().catch(()=>null).finally(()=>inflight.delete(key));inflight.set(key,work);return work;}
export function hydrateDestinationPhotos(root=document){for(const cover of root.querySelectorAll('[data-destination]')){if(cover.dataset.photoRequested)continue;cover.dataset.photoRequested='true';photo(cover.dataset.destination,cover.dataset.destinationCity).then(p=>{if(!p||!cover.isConnected)return;const img=cover.querySelector('.destination-image'),credit=cover.querySelector('.destination-credit');img.onload=()=>{cover.classList.add('has-destination-photo');credit.hidden=false;};img.onerror=()=>{img.hidden=true;credit.hidden=true;};img.hidden=false;img.src=p.url;credit.href=p.credit;credit.textContent=`Foto: ${p.author||'Wikimedia Commons'}${p.license?' · '+p.license:''}`;});}}
